        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 382.0, "series": [{"data": [[100.0, 2.0], [200.0, 1.0]], "isOverall": false, "label": "noticia-0", "isController": false}, {"data": [[300.0, 1.0], [100.0, 1.0], [500.0, 1.0]], "isOverall": false, "label": "noticia-1", "isController": false}, {"data": [[0.0, 11.0], [4400.0, 1.0], [2600.0, 1.0], [21000.0, 1.0], [100.0, 382.0], [400.0, 5.0], [200.0, 11.0], [800.0, 2.0], [3400.0, 1.0], [3700.0, 1.0], [500.0, 1.0]], "isOverall": false, "label": "link", "isController": false}, {"data": [[800.0, 1.0], [100.0, 82.0], [400.0, 1.0]], "isOverall": false, "label": "main", "isController": false}, {"data": [[0.0, 11.0], [300.0, 2.0], [700.0, 2.0], [100.0, 62.0], [400.0, 4.0], [900.0, 1.0], [1800.0, 1.0], [500.0, 1.0]], "isOverall": false, "label": "noticia", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 21000.0, "title": "Response Time Distribution"}},
